<template><view class="page"><view class="card"><text class="heading">加工产能与订单排产</text><view class="buttons"><button size="mini" @click="newPlan">新建排产</button><button size="mini" @click="showConfig=!showConfig">查看产能</button><button size="mini" @click="editCapacity">维护产能</button><button size="mini" @click="load">刷新</button></view><business-detail v-if="showConfig" :value="capacity"/></view><view v-if="error" class="error">{{error}}</view><view v-for="row in rows" :key="row.id" class="card" @click="open(row)"><text class="heading">{{row.planNo}}</text><text class="muted">{{label(row.status)}} · {{row.createdAt || row.createTime}}</text></view><button v-if="rows.length<total" @click="more">加载更多</button><view v-if="detail" class="card"><text class="heading">排产方案与执行</text><button size="mini" @click="exportSnapshot">导出当前方案</button><business-detail :value="detail"/><view class="buttons"><button v-if="detail.status==='DRAFT'" size="mini" @click="operate('厂长审批','approve',[note('reason','审批说明',true)])">厂长审批</button><button v-if="detail.status==='APPROVED'" size="mini" @click="operate('发布工单','publish',[])">发布工单</button><button v-if="['DRAFT','PUBLISHED'].includes(detail.status)" size="mini" @click="replan">{{detail.status==='DRAFT'?'拆批重算':'重排 / 插单'}}</button><button v-if="detail.status==='PUBLISHED'" size="mini" @click="operate('验收结案','close',[])">验收结案</button><button size="mini" @click="operate('取消计划','cancel',[note('reason','取消原因',true)])">取消计划</button></view><view v-for="conflict in detail.result?.conflicts || []" :key="conflict.jobKey" class="subcard"><text>{{conflict.jobKey}} · {{conflict.reason}}</text><button size="mini" @click="decide(conflict)">处理冲突</button></view><view v-for="work in detail.works || []" :key="work.id" class="subcard"><text>{{work.job_key}} · {{work.operation}} · {{label(work.status)}}</text><button v-if="work.status==='READY'" size="mini" @click="operate('核验到厂并开工','works/'+work.id,[yesno('arrivalConfirmed','原料已到厂'),text('arrivalEvidence','到厂凭据',true)],{action:'START'})">开工</button><button v-if="work.status==='RUNNING'" size="mini" @click="operate('登记工单完成','works/'+work.id,[reference('processRecordId','已完成加工记录','/process/records','id','processName',true)],{action:'COMPLETE'})">登记完成</button></view><view v-for="out in detail.outsource || []" :key="out.id" class="subcard"><text>{{out.job_key}} · 外协 {{out.quantity_kg}}kg</text><button v-if="out.status==='COMMISSIONED'" size="mini" @click="operate('外协验收','outsource/'+out.id+'/receipt',[text('traceCode','追溯码',true),note('acceptanceEvidence','验收凭据',true)])">验收</button></view></view>
<view v-if="editing||action" class="overlay"><view class="head"><text>{{editing?'编排加工任务':action?.title}}</text><button size="mini" :disabled="busy" @click="close">取消</button></view><scroll-view scroll-y class="body"><template v-if="editing"><business-fields :fields="baseFields" v-model="form"/><view v-for="(job,index) in jobs" :key="job.key" class="card"><text class="heading">拆批任务 {{index+1}}</text><business-fields :fields="jobFields(job)" :model-value="job" @update:model-value="updateJob(index,$event)"/><button size="mini" @click="jobs.splice(index,1)">移除任务</button></view><button size="mini" @click="addJob">添加拆批任务</button></template><business-fields v-else-if="action" :fields="action.fields" v-model="actionForm" :disabled="busy" @ready="ready=$event"/><view v-if="saveError" class="error">{{saveError}}</view><view style="height:50rpx"/></scroll-view><view class="bottom"><button class="primary" :loading="busy" :disabled="busy||(!editing&&!ready)" @click="editing?solve():sendAction()">{{editing?'计算并保存方案':action?.title}}</button></view></view></view></template>
<script setup lang="ts">
import {saveText} from '@/utils/business-files'
async function exportSnapshot(){try{if(!detail.value)throw new Error('请先选择方案');await saveText('加工排产.json',JSON.stringify(detail.value,null,2))}catch(e:any){error.value=e.message}}
import {ref} from 'vue'
import {onShow,onHide,onBackPress} from '@dcloudio/uni-app'
import {call,text,number,note,yesno,select,choice,reference,statusLabels,validateFields} from '@/api/native-business'
import type {Row,Field} from '@/api/native-business'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {productionContextVersion} from '@/utils/request'
import BusinessFields from '@/components/business-fields/business-fields.vue'
import BusinessDetail from '@/components/business-detail/business-detail.vue'
const rows=ref<Row[]>([]),total=ref(0),capacity=ref<Row>(),sources=ref<Row>(),detail=ref<Row>(),showConfig=ref(false),error=ref(''),saveError=ref(''),busy=ref(false),editing=ref(false),form=ref<Row>({}),jobs=ref<Row[]>([]),action=ref<{title:string;path:string;fields:Field[];base:Row}>(),actionForm=ref<Row>({}),ready=ref(false)
let page=1,scope=0,version=0
const label=(v:string)=>statusLabels[v]||v
const baseFields=[text('start','七天排程起点（年月日T时:分）',true),note('reason','重排 / 插单原因')]
const operations=choice({SPREADING:'摊青',FIXATION:'杀青',ROLLING:'揉捻',DRYING:'烘干',SORTING:'分选清洗',GRADING:'分级',PACKAGING:'分装',PRECOOL:'预冷',CUTING:'净切'})
function jobFields(job:Row):Field[]{return [text('key','任务编号',true),select('orderId','卖方订单',(sources.value?.orders||[]).filter((o:Row)=>['pending_confirm','pending','paid'].includes(o.status)).map((o:Row)=>({value:String(o.id),label:o.orderNo+' · '+(o.productName||'')})),true),select('itemId','订单明细',(sources.value?.orders?.find((o:Row)=>String(o.id)===String(job.orderId))?.items||[]).map((i:Row)=>({value:String(i.id),label:i.productName+' · '+i.quantity+i.unit})),true),select('batchId','原料批次',(sources.value?.batches||[]).map((b:Row)=>({value:String(b.id),label:b.batchNo+' · '+b.quantity+b.unit})),true),number('kg','本拆批数量（kg）',true,0.001),text('arrival','预计到厂（年月日T时:分）',true),{...select('route','工序路线（按勾选顺序）',operations,true),multiple:true},number('priority','急单级别（0—9）')]}
function updateJob(index:number,value:Row){if(value.orderId!==jobs.value[index].orderId)value.itemId='';jobs.value[index]=value}
async function load(){const token=++version;error.value='';try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');scope=productionContextVersion();const [list,c,s]=await Promise.all([call('/processing-schedules','GET',undefined,{pageNum:1,pageSize:20}),call('/processing-schedules/config'),call('/processing-schedules/sources')]);if(token!==version)return;rows.value=list.list;total.value=list.total;page=1;capacity.value=c;sources.value=s}catch(e:any){error.value=e.message}}
async function more(){try{const result=await call('/processing-schedules','GET',undefined,{pageNum:page+1,pageSize:20});rows.value.push(...result.list);total.value=result.total;page++}catch(e:any){error.value=e.message}}
async function open(row:Row){try{detail.value=await call('/processing-schedules/'+row.id)}catch(e:any){error.value=e.message}}
function newPlan(){form.value={start:'',reason:''};jobs.value=[];editing.value=true;saveError.value='';addJob()}
function addJob(){jobs.value.push({key:'JOB-'+Date.now().toString(36),route:[],priority:0})}
function replan(){form.value={...detail.value?.input,parentId:detail.value?.status==='PUBLISHED'?detail.value.id:undefined,reason:''};jobs.value=JSON.parse(JSON.stringify(detail.value?.input?.jobs||[]));editing.value=true}
function operate(title:string,path:string,fields:Field[],base:Row={}){action.value={title,path,fields,base};actionForm.value={};ready.value=false;saveError.value=''}
const capacityFields:Field[]=[text('sourceVersion','核验依据版本',true),number('categoryMinutes','品类切换清洗分钟',true),number('gradeMinutes','等级切换分钟',true),{...number('maxChanges','每日最多切换',true,1),max:20},{key:'resources',label:'设备工序资源',type:'array',required:true,children:[text('id','物理设备编号',true),text('name','设备名称',true),select('operation','工序',operations,true),number('kgPerHour','理论产能（kg/h）',true,0.001),{...number('availability','可用率（0—1）',true,0.01),max:1},text('availableFrom','最早可用时间',true),text('sourceEvidence','核验凭据',true),{key:'downtime',label:'停班 / 检修区间',type:'array',children:[text('start','开始时间',true),text('end','结束时间',true)]}]},{key:'providers',label:'外协厂商',type:'array',children:[text('id','供应商编号',true),text('name','厂商名称',true),number('pricePerKg','核验报价（元/kg）',true,0.001),number('capacityKg','承接能力（kg）',true,0.001),text('qualification','资质凭据',true),text('validUntil','资质有效期',true),text('categories','覆盖品类（逗号分隔）',true),yesno('traceable','在制品可追溯'),text('traceEvidence','追溯核验凭据',true)]}]
function editCapacity(){operate('保存产能口径','@config',capacityFields);actionForm.value=JSON.parse(JSON.stringify(capacity.value?.payload||{}));for(const p of actionForm.value.providers||[])if(Array.isArray(p.categories))p.categories=p.categories.join(',')}
function decide(conflict:Row){operate('冲突处置','decisions',[select('type','处理方式',choice({POSTPONE:'顺延',OUTSOURCE:'外协'}),true),select('providerId','已核验外协厂商',(detail.value?.input?.capacity?.providers||[]).map((p:Row)=>({value:p.id,label:p.name}))),number('cost','顺延成本（元）'),yesno('customerConfirmed','客户同意延期'),text('customerEvidence','客户同意凭据'),note('reason','处理原因',true)],{jobKey:conflict.jobKey})}
function close(){if(busy.value)return;editing.value=false;action.value=undefined}
async function solve(){if(busy.value)return;saveError.value='';try{if(scope!==productionContextVersion())throw new Error('业务范围已变更');if(!form.value.start||!jobs.value.length)throw new Error('请填写排程起点并添加任务');for(const job of jobs.value){for(const f of jobFields(job))if(f.required&&(!job[f.key]||(Array.isArray(job[f.key])&&!job[f.key].length)))throw new Error('请补全'+f.label);job.kg=Number(job.kg);job.priority=Number(job.priority||0);if(!(job.kg>0))throw new Error('拆批数量必须大于0')}busy.value=true;detail.value=await call('/processing-schedules/solve','POST',{...form.value,jobs:jobs.value});editing.value=false;await load()}catch(e:any){saveError.value=e.message}finally{busy.value=false}}
async function sendAction(){if(busy.value||!action.value||(!detail.value&&action.value.path!=='@config'))return;saveError.value='';try{if(scope!==productionContextVersion())throw new Error('业务范围已变更');const values={...action.value.base,...validateFields(action.value.fields,actionForm.value)};for(const f of action.value.fields){if(f.required&&(values[f.key]===undefined||values[f.key]===''))throw new Error('请填写'+f.label);if(f.type==='number'&&values[f.key]!==undefined&&values[f.key]!=='')values[f.key]=Number(values[f.key])}busy.value=true;if(action.value.path==='@config'){for(const p of values.providers||[])p.categories=String(p.categories).split(',').map((v:string)=>v.trim()).filter(Boolean);capacity.value=await call('/processing-schedules/config','PUT',values)}else detail.value=await call('/processing-schedules/'+detail.value!.id+'/'+action.value.path,'POST',values);action.value=undefined;await load()}catch(e:any){saveError.value=e.message}finally{busy.value=false}}
onShow(()=>void load());onHide(()=>{version++;editing.value=false;action.value=undefined;detail.value=undefined});onBackPress(()=>{if(busy.value)return true;if(editing.value||action.value){close();return true}return false})
</script>
<style scoped>.page{padding:24rpx;background:#f4f6f2}.card{padding:26rpx;margin-bottom:24rpx;background:#fff;border-radius:18rpx}.heading{display:block;font-size:31rpx;font-weight:600;margin-bottom:20rpx}.muted{font-size:25rpx;color:#738070}.buttons{display:flex;flex-wrap:wrap;gap:14rpx}.buttons button{margin:0;min-height:76rpx;font-size:24rpx}.subcard{padding:20rpx;background:#f3f6f0;border-radius:12rpx;margin:20rpx 0;font-size:26rpx}.subcard button{margin-top:16rpx}.error{padding:24rpx;background:#fff0e9;color:#a43e28;line-height:1.6;font-size:26rpx}.overlay{position:fixed;inset:0;top:var(--window-top,0px);z-index:90;background:#fff;display:flex;flex-direction:column}.head{display:flex;justify-content:space-between;align-items:center;padding:24rpx;font-size:30rpx}.head button{margin:0}.body{height:0;flex:1;box-sizing:border-box;padding:0 28rpx}.bottom{padding:20rpx 28rpx calc(20rpx + env(safe-area-inset-bottom))}.primary{background:#0f7a45;color:#fff;font-size:28rpx}</style>
